// Material PlayerCarPixels (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_atlas: texture_2d<f32>;
@group(2) @binding(2) var material_sampler: sampler;
const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: vec3f = in.color.xyz;
  let v1: vec2f = vec2f(1024.0, 1024.0);
  let v2: vec2f = (in.uv * v1);
  let v3: vec2f = floor(v2);
  let v4: vec2f = (v3 + 0.5);
  let v5: vec2f = (v4 / v1);
  let v6: vec4f = textureSample(tex_atlas, material_sampler, v5);
  let v7: vec3f = v6.xyz;
  let v8: f32 = in.color.w;
  let v9: vec3f = vec3f(v8);
  let v10: vec3f = mix(v0, v7, v9);
  let v11: f32 = v6.w;
  let v12: f32 = mix(1.0, v11, v8);
  out.base_color = v10;
  out.alpha = v12;
  return out;
}
